// O Error Trigger entrega { execution, workflow, trigger }.
// Alguns campos faltam dependendo de onde o crash aconteceu, entao le tudo
// defensivamente - este workflow NAO pode quebrar, senao o erro fica mudo.

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  const s = String(v)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/\u0000/g, '');
  return "'" + s + "'";
}

const e = $input.first().json || {};
const wf = e.workflow || {};
const ex = e.execution || {};
const err = ex.error || e.error || {};

const nomeWf = String(wf.name || 'desconhecido').slice(0, 40);
const etapa = String(err.node && err.node.name ? err.node.name : ex.lastNodeExecuted || '?').slice(0, 60);
const msg = String(err.message || 'sem mensagem').slice(0, 480);
const pilha = String(err.stack || err.description || '').slice(0, 2000);
const execId = ex.id || '?';
const execUrl = ex.url || '';

const sql =
  'INSERT INTO logs_execucao (workflow, etapa, status, mensagem, erro)\n' +
  'VALUES (' +
  [esc(nomeWf), esc(etapa), "'ERRO'", esc(msg), esc(pilha)].join(', ') +
  ')';

return [
  {
    json: {
      sql,
      nomeWf,
      etapa,
      msg,
      execId,
      execUrl,
    },
  },
];

